2172→// filesChangedInCommit returns the set of files changed in a commit by diffing against its parent.
2173→// When headTree and parentTree are provided, they are used directly to avoid redundant reads.
2174→func filesChangedInCommit(commit *object.Commit, headTree, parentTree *object.Tree) map[string]struct{} {
2175→	result := make(map[string]struct{})
2176→
2177→	commitTree := headTree
2178→	if commitTree == nil {
2179→		var err error
2180→		commitTree, err = commit.Tree()
2181→		if err != nil {
2182→			return result
2183→		}
2184→	}
2185→
2186→	if parentTree == nil && commit.NumParents() > 0 {
2187→		parent, err := commit.Parent(0)
2188→		if err != nil {
2189→			return result
2190→		}
2191→		parentTree, err = parent.Tree()
2192→		if err != nil {
2193→			return result
2194→		}
2195→	}
2196→
2197→	if parentTree == nil {
2198→		// Initial commit — all files are new
2199→		if iterErr := commitTree.Files().ForEach(func(f *object.File) error {
2200→			result[f.Name] = struct{}{}
2201→			return nil
2202→		}); iterErr != nil {
2203→			return result
2204→		}
2205→		return result
2206→	}
2207→
2208→	changes, err := parentTree.Diff(commitTree)
2209→	if err != nil {
2210→		return result
2211→	}
2212→	for _, change := range changes {
2213→		name := change.To.Name
2214→		if name == "" {
2215→			name = change.From.Name
2216→		}
2217→		result[name] = struct{}{}
2218→	}
2219→	return result

