 146→func TestDiffLines_ModifiedEstimation(t *testing.T) {
 147→	// Test diffLines with modifications (additions + removals)
 148→	// When we have both additions and removals, min(added, removed) represents modifications
 149→	checkpoint := "original1\noriginal2\noriginal3\n"
 150→	committed := "modified1\nmodified2\noriginal3\nnew line\n"
 151→
 152→	unchanged, added, removed := diffLines(checkpoint, committed)
 153→
 154→	// original3 is unchanged (1)
 155→	// original1, original2 removed (2)
 156→	// modified1, modified2, new line added (3)
 157→	if unchanged != 1 {
 158→		t.Errorf("expected 1 unchanged, got %d", unchanged)
 159→	}
 160→	if added != 3 {
 161→		t.Errorf("expected 3 added, got %d", added)
 162→	}
 163→	if removed != 2 {
 164→		t.Errorf("expected 2 removed, got %d", removed)
 165→	}
 166→
 167→	// Estimate modified lines: min(3, 2) = 2 modified
 168→	// humanModified = 2
 169→	// humanAdded = 3 - 2 = 1 (pure additions)
 170→	// humanRemoved = 2 - 2 = 0 (pure removals)
 171→	humanModified := min(added, removed)
 172→	humanAdded := added - humanModified
 173→	humanRemoved := removed - humanModified
 174→
 175→	if humanModified != 2 {
 176→		t.Errorf("expected 2 modified, got %d", humanModified)
 177→	}
 178→	if humanAdded != 1 {
 179→		t.Errorf("expected 1 pure added (after subtracting modified), got %d", humanAdded)
 180→	}
 181→	if humanRemoved != 0 {
 182→		t.Errorf("expected 0 pure removed (after subtracting modified), got %d", humanRemoved)
 183→	}
 184→}
