 186→// buildTestTree creates an object.Tree from a map of file paths to content.
 187→// This is a test helper for creating trees without a full git repository.
 188→func buildTestTree(t *testing.T, files map[string]string) *object.Tree {
 189→	t.Helper()
 190→
 191→	if len(files) == 0 {
 192→		return nil
 193→	}
 194→
 195→	// Use memory storage to build a tree
 196→	storage := memory.NewStorage()
 197→
 198→	// Create blob objects for each file
 199→	var entries []object.TreeEntry
 200→	for path, content := range files {
 201→		// Encode the blob
 202→		obj := storage.NewEncodedObject()
 203→		obj.SetType(plumbing.BlobObject)
 204→		writer, err := obj.Writer()
 205→		if err != nil {
 206→			t.Fatalf("failed to create blob writer: %v", err)
 207→		}
 208→		if _, err := writer.Write([]byte(content)); err != nil {
 209→			t.Fatalf("failed to write blob content: %v", err)
 210→		}
 211→		writer.Close()
 212→
 213→		// Store the blob
 214→		hash, err := storage.SetEncodedObject(obj)
 215→		if err != nil {
 216→			t.Fatalf("failed to store blob: %v", err)
 217→		}
 218→
 219→		// Create tree entry
 220→		entries = append(entries, object.TreeEntry{
 221→			Name: path,
 222→			Mode: 0o100644,
 223→			Hash: hash,
 224→		})
 225→	}
 226→
 227→	// Sort entries by name (required by git tree format)
 228→	sort.Slice(entries, func(i, j int) bool {
 229→		return entries[i].Name < entries[j].Name
 230→	})
 231→
 232→	// Create the tree
 233→	tree := &object.Tree{
 234→		Entries: entries,
 235→	}
 236→
 237→	// Encode and store the tree
 238→	obj := storage.NewEncodedObject()
 239→	obj.SetType(plumbing.TreeObject)
 240→	if err := tree.Encode(obj); err != nil {
 241→		t.Fatalf("failed to encode tree: %v", err)
 242→	}
 243→
 244→	hash, err := storage.SetEncodedObject(obj)
 245→	if err != nil {
 246→		t.Fatalf("failed to store tree: %v", err)
 247→	}
 248→
 249→	// Retrieve the tree
 250→	treeObj, err := object.GetTree(storage, hash)
 251→	if err != nil {
 252→		t.Fatalf("failed to get tree: %v", err)
 253→	}
 254→
 255→	return treeObj
 256→}
