 686→// TestCalculateAttributionWithAccumulated_UserEditsNonAgentFile tests the bug where
 687→// post-checkpoint user edits to files the agent never touched are undercounted.
 688→//
 689→// Bug scenario:
 690→//  1. Agent touches file1.go (added to filesTouched)
 691→//  2. User edits file2.go between checkpoints → captured in PromptAttributions
 692→//  3. User edits file2.go again AFTER last checkpoint, before commit
 693→//  4. BUG: Post-checkpoint calculation only looks at filesTouched (file1.go),
 694→//     missing the file2.go edits in step 3
 695→//
 696→// This causes undercounted user contributions and inflated agent percentage.
 697→func TestCalculateAttributionWithAccumulated_UserEditsNonAgentFile(t *testing.T) {
 698→	// Base: two files
 699→	baseTree := buildTestTree(t, map[string]string{
 700→		"file1.go": "package main\n",
 701→		"file2.go": "package util\n",
 702→	})
 703→
 704→	// Shadow (agent work): agent adds to file1.go only
 705→	// file2.go is NOT in shadow tree because it's not in filesTouched
 706→	shadowTree := buildTestTree(t, map[string]string{
 707→		"file1.go": "package main\n\nfunc agent1() {}\nfunc agent2() {}\n",
 708→	})
 709→
 710→	// Head (final commit): user adds more to file2.go AFTER last checkpoint
 711→	// file2.go has: 1 base line + 2 accumulated + 2 post-checkpoint = 5 lines total
 712→	headTree := buildTestTree(t, map[string]string{
 713→		"file1.go": "package main\n\nfunc agent1() {}\nfunc agent2() {}\n",
 714→		"file2.go": "package util\n\n// User edit 1\n// User edit 2\n// User edit 3\n",
 715→	})
 716→
 717→	// filesTouched only includes file1.go (agent-touched)
 718→	filesTouched := []string{"file1.go"}
 719→
 720→	// PromptAttributions captured user edits to file2.go between checkpoints
 721→	promptAttributions := []PromptAttribution{
 722→		{
 723→			CheckpointNumber: 1,
 724→			UserLinesAdded:   2, // User edit 1, 2 (between checkpoints)
 725→			UserLinesRemoved: 0,
 726→			UserAddedPerFile: map[string]int{"file2.go": 2}, // Tracks which file the edits were in
 727→		},
 728→	}
 729→
 730→	result := CalculateAttributionWithAccumulated(
 731→		context.Background(),
 732→		baseTree, shadowTree, headTree, filesTouched, promptAttributions,
 733→	)
 734→
 735→	if result == nil {
 736→		t.Fatal("expected non-nil result")
 737→	}
 738→
 739→	// Expected calculation:
 740→	// - Agent added 3 lines to file1.go (2 functions + 1 blank)
 741→	// - User added 2 lines to file2.go between checkpoints (from PromptAttribution)
 742→	// - User added 2 MORE lines to file2.go after last checkpoint (post-checkpoint)
 743→	// - Total user added: 2 + 2 = 4
 744→	// - agentLinesInCommit: 3
 745→	// - Total: 3 + 4 = 7
 746→	// - Agent percentage: 3/7 = 42.9%
 747→	//
 748→	// BUG (if not fixed): Post-checkpoint calculation only looks at file1.go,
 749→	// so it would miss the 2 post-checkpoint edits to file2.go:
 750→	// - Total user added: 2 + 0 = 2 (WRONG)
 751→	// - Total: 3 + 2 = 5 (WRONG)
 752→	// - Agent percentage: 3/5 = 60% (WRONG, inflated)
 753→
 754→	t.Logf("Attribution: agent=%d, human_added=%d, total=%d, percentage=%.1f%%",
 755→		result.AgentLines, result.HumanAdded, result.TotalCommitted, result.AgentPercentage)
 756→
 757→	if result.AgentLines != 3 {
 758→		t.Errorf("AgentLines = %d, want 3", result.AgentLines)
 759→	}
 760→
 761→	if result.HumanAdded != 4 {
 762→		t.Errorf("HumanAdded = %d, want 4 (2 between + 2 post-checkpoint, including file agent never touched)",
 763→			result.HumanAdded)
 764→	}
 765→
 766→	if result.TotalCommitted != 7 {
 767→		t.Errorf("TotalCommitted = %d, want 7 (3 agent + 4 user)", result.TotalCommitted)
 768→	}
 769→
 770→	// Agent percentage should be 3/7 = 42.9%
 771→	if result.AgentPercentage < 42.8 || result.AgentPercentage > 43.0 {
 772→		t.Errorf("AgentPercentage = %.1f%%, want ~42.9%% (not inflated)", result.AgentPercentage)
 773→	}
 774→}
