 776→// TestGetAllChangedFilesBetweenTrees tests the hash-based file change detection.
 777→func TestGetAllChangedFilesBetweenTrees(t *testing.T) {
 778→	storer := memory.NewStorage()
 779→
 780→	// Helper to create a blob and return its hash
 781→	//nolint:errcheck // Test helper - errors would cause test failures anyway
 782→	createBlob := func(content string) plumbing.Hash {
 783→		blob := storer.NewEncodedObject()
 784→		blob.SetType(plumbing.BlobObject)
 785→		writer, _ := blob.Writer()
 786→		_, _ = writer.Write([]byte(content))
 787→		_ = writer.Close()
 788→		hash, _ := storer.SetEncodedObject(blob)
 789→		return hash
 790→	}
 791→
 792→	// Helper to create a tree from file entries
 793→	//nolint:errcheck // Test helper - errors would cause test failures anyway
 794→	createTree := func(files map[string]string) *object.Tree {
 795→		var entries []object.TreeEntry
 796→		for name, content := range files {
 797→			entries = append(entries, object.TreeEntry{
 798→				Name: name,
 799→				Mode: 0o100644,
 800→				Hash: createBlob(content),
 801→			})
 802→		}
 803→		// Sort entries by name (git requirement)
 804→		sort.Slice(entries, func(i, j int) bool {
 805→			return entries[i].Name < entries[j].Name
 806→		})
 807→
 808→		tree := &object.Tree{Entries: entries}
 809→		treeObj := storer.NewEncodedObject()
 810→		_ = tree.Encode(treeObj)
 811→		hash, _ := storer.SetEncodedObject(treeObj)
 812→
 813→		// Re-decode to get proper Tree object with hash
 814→		decodedTree, _ := object.GetTree(storer, hash)
 815→		return decodedTree
 816→	}
