 928→// TestEstimateUserSelfModifications tests the LIFO heuristic for user self-modifications.
 929→func TestEstimateUserSelfModifications(t *testing.T) {
 930→	tests := []struct {
 931→		name                  string
 932→		accumulatedUserAdded  map[string]int
 933→		postCheckpointRemoved map[string]int
 934→		expectedSelfModified  int
 935→	}{
 936→		{
 937→			name:                  "no removals",
 938→			accumulatedUserAdded:  map[string]int{"file.go": 5},
 939→			postCheckpointRemoved: map[string]int{},
 940→			expectedSelfModified:  0,
 941→		},
 942→		{
 943→			name:                  "removals less than user added",
 944→			accumulatedUserAdded:  map[string]int{"file.go": 5},
 945→			postCheckpointRemoved: map[string]int{"file.go": 3},
 946→			expectedSelfModified:  3, // All 3 removals are self-modifications
 947→		},
 948→		{
 949→			name:                  "removals equal to user added",
 950→			accumulatedUserAdded:  map[string]int{"file.go": 5},
 951→			postCheckpointRemoved: map[string]int{"file.go": 5},
 952→			expectedSelfModified:  5, // All 5 removals are self-modifications
 953→		},
 954→		{
 955→			name:                  "removals exceed user added",
 956→			accumulatedUserAdded:  map[string]int{"file.go": 3},
 957→			postCheckpointRemoved: map[string]int{"file.go": 5},
 958→			expectedSelfModified:  3, // Only 3 are self-modifications, 2 must be agent lines
 959→		},
 960→		{
 961→			name:                  "no user additions to file",
 962→			accumulatedUserAdded:  map[string]int{},
 963→			postCheckpointRemoved: map[string]int{"file.go": 5},
 964→			expectedSelfModified:  0, // All removals target agent lines
 965→		},
 966→		{
 967→			name:                  "multiple files",
 968→			accumulatedUserAdded:  map[string]int{"a.go": 3, "b.go": 2},
 969→			postCheckpointRemoved: map[string]int{"a.go": 2, "b.go": 4},
 970→			expectedSelfModified:  4, // 2 from a.go + 2 from b.go (capped at user additions)
 971→		},
 972→		{
 973→			name:                  "removal from file user never touched",
 974→			accumulatedUserAdded:  map[string]int{"a.go": 5},
 975→			postCheckpointRemoved: map[string]int{"b.go": 3},
 976→			expectedSelfModified:  0, // User never added to b.go, so all removals are agent lines
 977→		},
 978→	}
 979→
 980→	for _, tt := range tests {
 981→		t.Run(tt.name, func(t *testing.T) {
 982→			result := estimateUserSelfModifications(tt.accumulatedUserAdded, tt.postCheckpointRemoved)
 983→			if result != tt.expectedSelfModified {
