 990→// TestCalculateAttributionWithAccumulated_UserSelfModification tests the per-file tracking fix:
 991→// when a user modifies their own previously-added lines (not agent lines),
 992→// it should NOT reduce the agent's contribution.
 993→//
 994→// Bug scenario before fix:
 995→// 1. Agent adds 10 lines
 996→// 2. User adds 5 lines of their own (captured in PromptAttribution)
 997→// 3. User later removes 3 of their own lines and adds 3 different ones
 998→// 4. OLD: humanModified=3 was subtracted from agent lines (WRONG)
 999→// 5. NEW: humanModified=3 but userSelfModified=3, so agent lines unchanged (CORRECT)
1000→func TestCalculateAttributionWithAccumulated_UserSelfModification(t *testing.T) {
1001→	// Base: empty file
1002→	baseTree := buildTestTree(t, map[string]string{
1003→		"main.go": "",
1004→	})
1005→
1006→	// Shadow (checkpoint state): agent added 10 lines, user added 5 lines between checkpoints
1007→	// The shadow includes both because it's a snapshot of the worktree at checkpoint time
1008→	shadowTree := buildTestTree(t, map[string]string{
1009→		"main.go": "agent1\nagent2\nagent3\nagent4\nagent5\nagent6\nagent7\nagent8\nagent9\nagent10\nuser1\nuser2\nuser3\nuser4\nuser5\n",
1010→	})
1011→
1012→	// Head (commit state): user removed 3 of their own lines and added 3 different ones
1013→	// Agent lines are unchanged
1014→	headTree := buildTestTree(t, map[string]string{
1015→		"main.go": "agent1\nagent2\nagent3\nagent4\nagent5\nagent6\nagent7\nagent8\nagent9\nagent10\nuser1\nuser2\nnew_user1\nnew_user2\nnew_user3\n",
1016→	})
1017→
1018→	filesTouched := []string{"main.go"}
1019→
1020→	// PromptAttribution captured that user added 5 lines between checkpoints
1021→	promptAttributions := []PromptAttribution{
1022→		{
1023→			CheckpointNumber: 2,
1024→			UserLinesAdded:   5,
1025→			UserLinesRemoved: 0,
1026→			UserAddedPerFile: map[string]int{"main.go": 5}, // KEY: per-file tracking
1027→		},
1028→	}
1029→
1030→	result := CalculateAttributionWithAccumulated(
1031→		context.Background(),
1032→		baseTree, shadowTree, headTree, filesTouched, promptAttributions,
1033→	)
1034→
1035→	if result == nil {
1036→		t.Fatal("expected non-nil result")
1037→	}
1038→
1039→	// Expected calculation with per-file tracking:
1040→	// - base → shadow: 15 lines added (10 agent + 5 user)
1041→	// - accumulatedUserAdded: 5 (from PromptAttribution)
1042→	// - totalAgentAdded: 15 - 5 = 10
1043→	// - shadow → head: +3 lines added, -3 lines removed (user modification)
1044→	// - totalUserAdded: 5 + 3 = 8
1045→	// - totalUserRemoved: 3
1046→	// - totalHumanModified: min(8, 3) = 3
1047→	// - userSelfModified: min(3 removed from main.go, 5 user added to main.go) = 3
1048→	// - humanModifiedAgent: 3 - 3 = 0 (no agent lines were modified!)
1049→	// - agentLinesInCommit: 10 - 0 - 0 = 10 (CORRECT: agent lines unchanged)
1050→	// - Total: 10 + 5 = 15
1051→	// - Agent percentage: 10/15 = 66.7%
