package gitops

import (
	"bytes"
	"context"
	"fmt"
	"os/exec"
	"strings"
)

// DiffTreeFiles returns the set of files changed between two commits using git diff-tree.
// For initial commits (commit1 is empty), use --root mode.
// Returns a map of file paths for O(1) lookup.
func DiffTreeFiles(ctx context.Context, commit1, commit2 string) (map[string]struct{}, error) {
	files, err := diffTreeRaw(ctx, commit1, commit2)
	if err != nil {
		return nil, err
	}

	result := make(map[string]struct{}, len(files))
	for _, f := range files {
		result[f] = struct{}{}
	}
	return result, nil
}

// DiffTreeFileList returns the list of files changed between two commits using git diff-tree.
// For initial commits (commit1 is empty), use --root mode.
func DiffTreeFileList(ctx context.Context, commit1, commit2 string) ([]string, error) {
	return diffTreeRaw(ctx, commit1, commit2)
}

// diffTreeRaw runs git diff-tree and returns the list of changed file paths.
func diffTreeRaw(ctx context.Context, commit1, commit2 string) ([]string, error) {
	var cmd *exec.Cmd
	if commit1 == "" {
		// Initial commit (no parent): list all files in the tree
		cmd = exec.CommandContext(ctx, "git", "diff-tree", "--root", "--no-commit-id", "-r", "-z", commit2) //nolint:gosec // commit hashes from trusted internal state
	} else {
		cmd = exec.CommandContext(ctx, "git", "diff-tree", "--no-commit-id", "-r", "-z", commit1, commit2) //nolint:gosec // commit hashes from trusted internal state
	}

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("git diff-tree failed: %w: %s", err, strings.TrimSpace(stderr.String()))
	}

	return parseDiffTreeOutput(stdout.Bytes()), nil
}

// parseDiffTreeOutput parses null-separated git diff-tree -r -z output.
// The format is: :<old-mode> <new-mode> <old-hash> <new-hash> <status>\0<path>\0
// For renames/copies: :<old-mode> <new-mode> <old-hash> <new-hash> <status>\0<old-path>\0<new-path>\0
func parseDiffTreeOutput(data []byte) []string {
	if len(data) == 0 {
		return nil
	}

	// Split on null bytes
	parts := bytes.Split(data, []byte{0})

	var files []string
	i := 0
	for i < len(parts) {
		part := string(parts[i])

		if strings.HasPrefix(part, ":") {
			// This is a status line like ":100644 100644 abc123 def456 M"
			// The next part(s) are the path(s)
			status := extractStatus(part)
			i++
			if i >= len(parts) {
				break
			}

			// First path
			path := string(parts[i])
			if path != "" {
				files = append(files, path)
			}
			i++

			// Renames (R) and copies (C) have a second path
			if (status == 'R' || status == 'C') && i < len(parts) {
				path2 := string(parts[i])
				if path2 != "" && !strings.HasPrefix(path2, ":") {
					files = append(files, path2)
					i++
				}
			}
		} else if part == "" {
			// Skip empty parts (trailing null byte)
			i++
		} else {
			// Unexpected content, skip
			i++
		}
	}

	return files
}

// extractStatus extracts the single-char status from a diff-tree status line.
// Input format: ":100644 100644 abc123... def456... M" or similar
func extractStatus(statusLine string) byte {
	// Status is the last non-space character in the metadata portion
	// Format: :<old-mode> <new-mode> <old-hash> <new-hash> <status-letter>[score]
	trimmed := strings.TrimSpace(statusLine)
	if len(trimmed) == 0 {
		return 0
	}

	// Split by spaces and take the last field
	fields := strings.Fields(trimmed)
	if len(fields) < 5 {
		return 0
	}
	statusField := fields[4]
	if len(statusField) == 0 {
		return 0
	}
	return statusField[0]
}

package gitops

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"testing"
)

// initTestRepo creates a temp git repo and returns its path.
func initTestRepo(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()

	run := func(args ...string) {
		t.Helper()
		cmd := exec.Command("git", args...)
		cmd.Dir = dir
		cmd.Env = append(os.Environ(),
			"GIT_AUTHOR_NAME=Test",
			"GIT_AUTHOR_EMAIL=test@test.com",
			"GIT_COMMITTER_NAME=Test",
			"GIT_COMMITTER_EMAIL=test@test.com",
		)
		out, err := cmd.CombinedOutput()
		if err != nil {
			t.Fatalf("git %v failed: %v\n%s", args, err, out)
		}
	}

	run("init", "-b", "main")
	run("config", "commit.gpgsign", "false")

	return dir
}

// commitHash returns the HEAD commit hash.
func commitHash(t *testing.T, dir string) string {
	t.Helper()
	cmd := exec.Command("git", "rev-parse", "HEAD")
	cmd.Dir = dir
	out, err := cmd.Output()
	if err != nil {
		t.Fatalf("git rev-parse HEAD failed: %v", err)
	}
	return string(out[:len(out)-1]) // trim newline
}

func writeFile(t *testing.T, dir, name, content string) {
	t.Helper()
	path := filepath.Join(dir, name)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

func gitAdd(t *testing.T, dir string, files ...string) {
	t.Helper()
	args := append([]string{"add"}, files...)
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git add failed: %v\n%s", err, out)
	}
}

func gitCommit(t *testing.T, dir, msg string) {
	t.Helper()
	cmd := exec.Command("git", "commit", "-m", msg, "--allow-empty")
	cmd.Dir = dir
	cmd.Env = append(os.Environ(),
		"GIT_AUTHOR_NAME=Test",
		"GIT_AUTHOR_EMAIL=test@test.com",
		"GIT_COMMITTER_NAME=Test",
		"GIT_COMMITTER_EMAIL=test@test.com",
	)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("git commit failed: %v\n%s", err, out)
	}
}

func TestDiffTreeFiles_NormalCommit(t *testing.T) {
	t.Parallel()
	dir := initTestRepo(t)

	// Initial commit with file1
	writeFile(t, dir, "file1.go", "package main\n")
	gitAdd(t, dir, "file1.go")
	gitCommit(t, dir, "initial")
	commit1 := commitHash(t, dir)

	// Second commit: modify file1, add file2
	writeFile(t, dir, "file1.go", "package main\n\nfunc main() {}\n")
	writeFile(t, dir, "file2.go", "package util\n")
	gitAdd(t, dir, "file1.go", "file2.go")
	gitCommit(t, dir, "second")
	commit2 := commitHash(t, dir)

	// Must run from the repo directory
	origDir, _ := os.Getwd()
	if err := os.Chdir(dir); err != nil {
		t.Fatal(err)
	}
	defer os.Chdir(origDir) //nolint:errcheck // test cleanup

	result, err := DiffTreeFiles(context.Background(), commit1, commit2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	if len(result) != 2 {
		t.Fatalf("expected 2 changed files, got %d: %v", len(result), result)
	}
	if _, ok := result["file1.go"]; !ok {
		t.Error("expected file1.go in result")
	}
	if _, ok := result["file2.go"]; !ok {
		t.Error("expected file2.go in result")
	}
}

func TestDiffTreeFiles_InitialCommit(t *testing.T) {
	t.Parallel()
