  1→package gitops
  2→
  3→import (
  4→	"bytes"
  5→	"context"
  6→	"fmt"
  7→	"os/exec"
  8→	"strings"
  9→)
 10→
 11→// DiffTreeFiles returns the set of files changed between two commits using git diff-tree.
 12→// For initial commits (commit1 is empty), use --root mode.
 13→// Returns a map of file paths for O(1) lookup.
 14→func DiffTreeFiles(ctx context.Context, commit1, commit2 string) (map[string]struct{}, error) {
 15→	files, err := diffTreeRaw(ctx, commit1, commit2)
 16→	if err != nil {
 17→		return nil, err
 18→	}
 19→
 20→	result := make(map[string]struct{}, len(files))
 21→	for _, f := range files {
 22→		result[f] = struct{}{}
 23→	}
 24→	return result, nil
 25→}
 26→
 27→// DiffTreeFileList returns the list of files changed between two commits using git diff-tree.
 28→// For initial commits (commit1 is empty), use --root mode.
 29→func DiffTreeFileList(ctx context.Context, commit1, commit2 string) ([]string, error) {
 30→	return diffTreeRaw(ctx, commit1, commit2)
 31→}
 32→
 33→// diffTreeRaw runs git diff-tree and returns the list of changed file paths.
 34→func diffTreeRaw(ctx context.Context, commit1, commit2 string) ([]string, error) {
 35→	var cmd *exec.Cmd
 36→	if commit1 == "" {
 37→		// Initial commit (no parent): list all files in the tree
 38→		cmd = exec.CommandContext(ctx, "git", "diff-tree", "--root", "--no-commit-id", "-r", "-z", commit2)
 39→	} else {
 40→		cmd = exec.CommandContext(ctx, "git", "diff-tree", "--no-commit-id", "-r", "-z", commit1, commit2)
 41→	}
 42→
 43→	var stdout, stderr bytes.Buffer
 44→	cmd.Stdout = &stdout
 45→	cmd.Stderr = &stderr
 46→
 47→	if err := cmd.Run(); err != nil {
 48→		return nil, fmt.Errorf("git diff-tree failed: %w: %s", err, strings.TrimSpace(stderr.String()))
 49→	}
 50→
 51→	return parseDiffTreeOutput(stdout.Bytes()), nil
 52→}
 53→
 54→// parseDiffTreeOutput parses null-separated git diff-tree -r -z output.
 55→// The format is: :<old-mode> <new-mode> <old-hash> <new-hash> <status>\0<path>\0
 56→// For renames/copies: :<old-mode> <new-mode> <old-hash> <new-hash> <status>\0<old-path>\0<new-path>\0
 57→func parseDiffTreeOutput(data []byte) []string {
 58→	if len(data) == 0 {
 59→		return nil
 60→	}
 61→
 62→	// Split on null bytes
 63→	parts := bytes.Split(data, []byte{0})
 64→
 65→	var files []string
 66→	i := 0
 67→	for i < len(parts) {
 68→		part := string(parts[i])
 69→
 70→		if strings.HasPrefix(part, ":") {
 71→			// This is a status line like ":100644 100644 abc123 def456 M"
 72→			// The next part(s) are the path(s)
 73→			status := extractStatus(part)
 74→			i++
 75→			if i >= len(parts) {
 76→				break
 77→			}
 78→
 79→			// First path
 80→			path := string(parts[i])
 81→			if path != "" {
 82→				files = append(files, path)
 83→			}
 84→			i++
 85→
 86→			// Renames (R) and copies (C) have a second path
 87→			if (status == 'R' || status == 'C') && i < len(parts) {
 88→				path2 := string(parts[i])
 89→				if path2 != "" && !strings.HasPrefix(path2, ":") {
 90→					files = append(files, path2)
 91→					i++
 92→				}
 93→			}
 94→		} else if part == "" {
 95→			// Skip empty parts (trailing null byte)
 96→			i++
 97→		} else {
 98→			// Unexpected content, skip
 99→			i++
100→		}
101→	}
102→
103→	return files
104→}
105→
106→// extractStatus extracts the single-char status from a diff-tree status line.
107→// Input format: ":100644 100644 abc123... def456... M" or similar
108→func extractStatus(statusLine string) byte {
109→	// Status is the last non-space character in the metadata portion
110→	// Format: :<old-mode> <new-mode> <old-hash> <new-hash> <status-letter>[score]
111→	trimmed := strings.TrimSpace(statusLine)
112→	if len(trimmed) == 0 {
113→		return 0
114→	}
115→
116→	// Split by spaces and take the last field
117→	fields := strings.Fields(trimmed)
118→	if len(fields) < 5 {
119→		return 0
120→	}
121→	statusField := fields[4]
122→	if len(statusField) == 0 {
123→		return 0
124→	}
125→	return statusField[0]
126→}
